{"command": "python3 <<'PY'
import subprocess, os, shutil, re, base64, zlib, json
EXE="/workspace/executable"
def run(*args, env=None, cwd="/tmp"):
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.run([EXE]+list(args), capture_output=True, text=True, cwd=cwd, env=e)
    return p
def decode(s):
    pad=len(s)%4
    if pad: s+='='*(4-pad)
    return json.loads(zlib.decompress(base64.urlsafe_b64decode(s)))

tmp="/tmp/direnvtest-shells"
shutil.rmtree(tmp, ignore_errors=True)
os.makedirs(tmp+"/proj")
open(tmp+"/proj/.envrc","w").write("export FOO=foo\nexport BAR='a b\\n c'\n")
p=run("allow", ".", cwd=tmp+"/proj", env={"HOME":tmp})
print("allow", p.returncode)

for shell in ["bash","zsh","fish","tcsh","elvish","pwsh","murex","json","vim","gha","gzenv","systemd"]:
    p=run("export", shell, cwd=tmp+"/proj", env={"HOME":tmp})
    print(f"=== export {shell} rc={p.returncode} ===")
    print("STDOUT:", repr(p.stdout[:2000]))
    print("STDERR:", repr(p.stderr[:500]))
    print()
PY"}

