func parseTOMLString(v string) string {
	v = strings.TrimSpace(v)
	if len(v) >= 2 && ((v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'')) {
		inner := v[1 : len(v)-1]
		// handle escapes for double quotes? Simplify: unescape \" \\ \n etc? TOML basic strings handle escapes. We'll do minimal.
		inner = strings.ReplaceAll(inner, `\"`, `"`)
		inner = strings.ReplaceAll(inner, `\\`, `\`)
		inner = strings.ReplaceAll(inner, `\n`, "\n")
		inner = strings.ReplaceAll(inner, `\t`, "\t")
		return inner
	}
	return v
}

func parseTOMLBool(v string) bool {
	v = strings.TrimSpace(v)
	return v == "true" || v == "True" || v == "TRUE" || v == "1"
}

func parseTOMLArray(v string) []string {
	v = strings.TrimSpace(v)
	if !strings.HasPrefix(v, "[") {
		return nil
	}
	// find matching ]? Assume single line array.
	inner := strings.TrimSpace(v[1:])
	if strings.HasSuffix(inner, "]") {
		inner = inner[:len(inner)-1]
	}
	var res []string
	// split by comma respecting quotes
	var cur strings.Builder
	inQ := byte(0)
	for i := 0; i < len(inner); i++ {
		ch := inner[i]
		if inQ != 0 {
			if ch == inQ {
				inQ = 0
			}
			cur.WriteByte(ch)
		} else {
			if ch == '"' || ch == '\'' {
				inQ = ch
				cur.WriteByte(ch)
			} else if ch == ',' {
				s := strings.TrimSpace(cur.String())
				if s != "" {
					res = append(res, parseTOMLString(s))
				}
				cur.Reset()
			} else {
				cur.WriteByte(ch)
			}
		}
	}
	s := strings.TrimSpace(cur.String())
	if s != "" {
		res = append(res, parseTOMLString(s))
	}
	return res
}

