		inner = strings.ReplaceAll(inner, `\\`, `\`)
		inner = strings.ReplaceAll(inner, `\n`, "\n")
		inner = strings.ReplaceAll(inner, `\t`, "\t")
		return inner
	}
	return v
}

func parseTOMLBool(v string) bool {
	v = strings.TrimSpace(v)
	return v == "true" || v == "True" || v == "TRUE" || v == "1"
