// Very simple TOML parser for direnv.toml: handles [global] and [whitelist] with string, bool, duration, arrays
func parseTOML(data string, c *Config) {
	section := ""
	lines := strings.Split(data, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.TrimSpace(line[1 : len(line)-1])
			continue
		}
		// key = value
		idx := strings.Index(line, "=")
		if idx < 0 {
			continue
		}
		key := strings.TrimSpace(line[:idx])
		val := strings.TrimSpace(line[idx+1:])
		// strip comments? TOML allows # after value, but values may contain # inside strings. Simplify: if # outside quotes, strip.
		// For our simple cases, just handle.
		if section == "global" {
			switch key {
			case "bash_path":
				c.BashPath = parseTOMLString(val)
			case "disable_stdin":
				c.DisableStdin = parseTOMLBool(val)
			case "warn_timeout":
				s := parseTOMLString(val)
				if d, err := time.ParseDuration(s); err == nil {
					c.WarnTimeout = d
				}
			case "log_format":
				c.LogFormat = parseTOMLString(val)
			case "log_filter":
				s := parseTOMLString(val)
				if s != "" {
					if re, err := regexp.Compile(s); err == nil {
						c.LogFilter = re
					}
				}
			case "load_dotenv":
				c.LoadDotenv = parseTOMLBool(val)
			case "strict_env":
				c.StrictEnv = parseTOMLBool(val)
			case "hide_env_diff":
				c.HideEnvDiff = parseTOMLBool(val)
			}
		} else if section == "whitelist" {
			switch key {
			case "prefix":
				arr := parseTOMLArray(val)
				for _, v := range arr {
					v = expandWhitelistPath(v)
					c.WhitelistPrefix = append(c.WhitelistPrefix, v)
				}
			case "exact":
				arr := parseTOMLArray(val)
				for _, v := range arr {
					v = expandWhitelistPath(v)
					// if directory, append /.envrc? Original: if directory name passed, treat as if /.envrc appended. How to detect directory? If path doesn't end with .envrc or .env? Actually exact can be dir or file. If it's a dir (exists and is dir?) or if it doesn't end with .envrc/.env? Let's check: man says "Each string can be a directory name or the full path to an .envrc file. If a directory name is passed, it will be treated as if it had been passed as itself with /.envrc appended."
					// So if path ends with .envrc or .env, keep as is, else append /.envrc. But what if path is like /tmp/bar (dir) vs /tmp/bar/.envrc (file)? We'll implement: if base is .envrc or .env, keep, else append /.envrc.
					base := filepath.Base(v)
					if base != ".envrc" && base != ".env" {
						// check if it's a dir? Always append? Let's append.
						v = filepath.Join(v, ".envrc")
					}
					c.WhitelistExact[v] = true
				}
			}
		}
	}
}

func expandWhitelistPath(p string) string {
	if strings.HasPrefix(p, "~/") {
		home := os.Getenv("HOME")
		return filepath.Join(home, strings.TrimPrefix(p, "~/"))
	}
	if p == "~" {
		return os.Getenv("HOME")
	}
	return p
}

func parseTOMLString(v string) string {
	v = strings.TrimSpace(v)
	if len(v) >= 2 && ((v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'')) {
		inner := v[1 : len(v)-1]
		// handle escapes for double quotes? Simplify: unescape \" \\ \n etc? TOML basic strings handle escapes. We'll do minimal.
		inner = strings.ReplaceAll(inner, `\"`, `"`)
		inner = strings.ReplaceAll(inner, `\\`, `\`)
		inner = strings.ReplaceAll(inner, `\n`, "\n")
		inner = strings.ReplaceAll(inner, `\t`, "\t")
		return inner
	}
	return v
}

func parseTOMLBool(v string) bool {
	v = strings.TrimSpace(v)
	return v == "true" || v == "True" || v == "TRUE" || v == "1"
}

func parseTOMLArray(v string) []string {
	v = strings.TrimSpace(v)
	if !strings.HasPrefix(v, "[") {
		return nil
	}
	// find matching ]? Assume single line array.
	inner := strings.TrimSpace(v[1:])
	if strings.HasSuffix(inner, "]") {
		inner = inner[:len(inner)-1]
	}
	var res []string
	// split by comma respecting quotes
	var cur strings.Builder
	inQ := byte(0)
	for i := 0; i < len(inner); i++ {
		ch := inner[i]
		if inQ != 0 {
			if ch == inQ {
				inQ = 0
			}
			cur.WriteByte(ch)
		} else {
			if ch == '"' || ch == '\'' {
				inQ = ch
				cur.WriteByte(ch)
			} else if ch == ',' {
				s := strings.TrimSpace(cur.String())
				if s != "" {
					res = append(res, parseTOMLString(s))
				}
				cur.Reset()
			} else {
				cur.WriteByte(ch)
			}
		}
	}
	s := strings.TrimSpace(cur.String())
	if s != "" {
		res = append(res, parseTOMLString(s))
	}
	return res
}

