func compressAndB64(data []byte) string {
	var buf bytes.Buffer
	w, _ := zlib.NewWriterLevel(&buf, zlib.DefaultCompression)
	w.Write(data)
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes())
}

func decodeB64AndDecompress(s string) ([]byte, error) {
	// add padding if needed? URLEncoding expects padding, but our strings already have padding. Just decode.
	// Handle missing padding (RawURLEncoding)? Try both.
	var raw []byte
	var err error
	raw, err = base64.URLEncoding.DecodeString(s)
	if err != nil {
		// try raw (no padding)
		if s2 := s; len(s2)%4 != 0 {
			s2 += strings.Repeat("=", 4-len(s2)%4)
		} else {
			// try standard?
		}
		raw, err = base64.URLEncoding.DecodeString(s)
		if err != nil {
			raw, err = base64.RawURLEncoding.DecodeString(strings.TrimRight(s, "="))
		}
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()
