func buildWatches(c *Config, rcPath string) []Watch {
	var watches []Watch
	watches = append(watches, statWatch(rcPath))
	// allow and deny paths
	allowPath := getAllowPathForStatus(c, rcPath)
	watches = append(watches, statWatch(allowPath))
	denyPath := denyPathFor(c, rcPath)
	watches = append(watches, statWatch(denyPath))
	return watches
}

func watchesEqual(a, b []Watch) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].Path != b[i].Path || a[i].Modtime != b[i].Modtime || a[i].Exists != b[i].Exists {
			return false
		}
	}
	return true
}

func isWatchesStale(current []Watch, stored []Watch) bool {
	// Compare current filesystem state vs stored watches (from DIRENV_WATCHES)?
	// Stored watches are list of paths with old modtimes? Actually stored watches are encoded with old modtimes (when last exported). Current watches are freshly statted. If any differ in modtime/exists, stale.
	// But stored watches also include allow/deny paths which may have changed due to content hash change (different path, not just mtime). In that case, lengths differ or paths differ, so stale.
	if len(current) != len(stored) {
		return true
	}
	for i := range current {
		if current[i].Path != stored[i].Path {
			return true
		}
		if current[i].Exists != stored[i].Exists || current[i].Modtime != stored[i].Modtime {
			return true
		}
	}
	return false
}

