func serializeShell(shell string, diff map[string]*string) string {
	switch shell {
	case "bash":
		return exportBash(diff)
	case "zsh":
		return exportZsh(diff)
	case "fish":
		return exportFish(diff)
	case "tcsh":
		return exportTcsh(diff)
	case "elvish":
		return exportElvish(diff)
	case "murex":
		return exportMurex(diff)
	case "json":
		return exportJson(diff)
	case "vim":
		return exportVim(diff)
	case "pwsh":
		return exportPwsh(diff)
	case "gha":
		return exportGha(diff)
	case "gzenv":
		return exportGzenv(diff)
	case "systemd":
		return exportSystemd(diff)
	default:
		return ""
	}
}

