PYEOF
cat > /tmp/new_tcsh.txt <<'EOF'
func tcshEscape(val string) string {
	if val == "" {
		return "''"
	}
	isSafe := func(ch byte) bool {
		if (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') {
			return true
		}
		switch ch {
		case '_', ',', '.', '/', '@', '-', '^', ']', '`':
			return true
		}
		return false
	}
	safe := true
	for i := 0; i < len(val); i++ {
		if !isSafe(val[i]) {
			safe = false
			break
		}
	}
	if safe {
		return val
	}
	var b strings.Builder
	for i := 0; i < len(val); i++ {
		ch := val[i]
		if isSafe(ch) {
			b.WriteByte(ch)
			continue
		}
		switch ch {
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		case ' ':
			b.WriteString("\\ ")
		case '\n':
			b.WriteString("\\n")
		case '\t':
			b.WriteString("\\t")
		case '\r':
			b.WriteString("\\r")
		case '"':
			b.WriteString("\"\"\"")
		default:
			if ch < 32 || ch >= 127 {
				fmt.Fprintf(&b, "\\x%02x", ch)
			} else {
				b.WriteByte('"')
				b.WriteByte(ch)
				b.WriteByte('"')
			}
		}
	}
	return b.String()
}

// vim
EOF
